/// What yq's `-o=shell` key rule leaves of `c` above U+007F once it is decomposed with NFKD: the
/// ASCII letters and digits of the decomposition, `_` for its other printable ASCII, and nothing
/// for a character with no such part (a combining mark, a letter of another script).
pub(super) fn ascii_of_nfkd(c: char, out: &mut alloc::string::String) {
    let cp = c as u32;
    let at = ROWS.partition_point(|&(start, _, _)| start <= cp);
    let Some(&(start, count, text)) = at.checked_sub(1).and_then(|at| ROWS.get(at)) else {
        return;
    };
    if cp >= start + count {
        return;
    }
    if count == 1 {
        out.push_str(text);
    } else if let Some(first) = text.chars().next() {
        if let Some(letter) = char::from_u32(first as u32 + (cp - start)) {
            out.push(letter);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloc::string::String;

    fn of(text: &str) -> String {
        let mut out = String::new();
        for c in text.chars() {
            ascii_of_nfkd(c, &mut out);
        }
        out
    }

    #[test]
    fn accents_ligatures_and_width_forms_keep_their_ascii() {
        assert_eq!(of("éñò"), "eno");
        assert_eq!(of("ﬁ"), "fi");
        assert_eq!(of("１Ａｚ"), "1Az");
        assert_eq!(of("²³"), "23");
        assert_eq!(of("…"), "___");
        assert_eq!(of("\u{a0}"), "_");
        assert_eq!(of("№"), "No");
    }

    #[test]
    fn what_has_no_ascii_part_is_nothing() {
        assert_eq!(of("א日本\u{301}"), "");
        assert_eq!(of("\u{10ffff}"), "");
    }

    #[test]
    fn the_table_is_sorted_and_its_runs_do_not_overlap() {
        for pair in ROWS.windows(2) {
            assert!(pair[0].0 + pair[0].1 <= pair[1].0, "{pair:?}");
        }
        assert_eq!(UNICODE_VERSION, "15.0.0");
    }
}
